```python
from cyclopts import App

app = App(name="myapp")


@app.default
def status():
    """Show the current status when no subcommand is given."""
    print("status: idle")


@app.command
def start():
    """Start the service."""
    print("starting...")


@app.command
def stop():
    """Stop the service."""
    print("stopping...")


if __name__ == "__main__":
    app()
